#!/usr/bin/env python3
# Offline CPU-serving checks: effective CPU budget, occupancy planning,
# NUMA capacity and traffic, cache/TLB panel bounds, roofline lower bound.
# No files, processes, network, project imports or hardware counters.
from fractions import Fraction
import sys


def check(name, cond, detail=''):
    if not cond:
        raise AssertionError(name + (' ' + detail if detail else ''))
    print('PASS: ' + name + (' ' + detail if detail else ''))


def expect_error(name, fn, *args):
    try:
        fn(*args)
    except (ValueError, ZeroDivisionError):
        print('PASS: ' + name)
        return
    raise AssertionError(name + ' did not reject invalid input')


def detect(name, ref_value, bad_value):
    if ref_value == bad_value:
        raise AssertionError(name + ' negative control was not distinguished')
    print('PASS: negative control detected: ' + name)


def effective_cores(cpuset_eff, quota, period):
    if cpuset_eff < 0:
        raise ValueError('cpuset_eff must be non-negative')
    if quota is not None:
        if quota < 0:
            raise ValueError('quota must be non-negative')
        if period is None or period <= 0:
            raise ValueError('period must be positive')
    p = Fraction(cpuset_eff, 1)
    if quota is None:
        return p
    q = Fraction(quota, period)
    return p if p < q else q


def model_slots(cpuset_eff, quota, period, host_reserve):
    if host_reserve < 0:
        raise ValueError('host_reserve must be non-negative')
    s = effective_cores(cpuset_eff, quota, period) - host_reserve
    return s if s > 0 else Fraction(0)


def plan_ok(workers, threads, cpuset_eff, quota, period, host_reserve):
    if workers < 0 or threads < 0:
        raise ValueError('workers and threads must be non-negative')
    if workers == 0:
        return True
    if threads == 0:
        return False
    return Fraction(workers * threads, 1) <= model_slots(cpuset_eff, quota, period, host_reserve)


def bad_plan_ok_host_cores(workers, threads, host_cores, host_reserve):
    return Fraction(workers * threads, 1) <= Fraction(host_cores, 1) - host_reserve


def per_domain_resident(mode, weight_mib, kv_mib):
    w = Fraction(weight_mib, 1)
    kv = Fraction(kv_mib, 1)
    if mode == 'full':
        return [w, w], [kv, kv]
    if mode == 'shared':
        half_w = Fraction(0, 1)
        half_kv = kv / 2
        return [w, half_w], [half_kv, half_kv]
    if mode == 'sharded':
        half_w = w / 2
        half_kv = kv / 2
        return [half_w, half_w], [half_kv, half_kv]
    raise ValueError('unknown mode')


def capacity_ok(mode, weight_mib, kv_mib, cap_mib):
    weights, kvs = per_domain_resident(mode, weight_mib, kv_mib)
    return all(weights[i] + kvs[i] <= cap_mib for i in range(2))


def bad_capacity_total(mode, weight_mib, kv_mib, cap_mib):
    return weight_mib + kv_mib <= 2 * cap_mib


def traffic_mib(mode, weight_mib):
    w = Fraction(weight_mib, 1)
    if mode == 'full':
        return 2 * w, Fraction(0, 1), 2 * w
    if mode == 'shared':
        return w / 2, w / 2, w
    if mode == 'sharded':
        return w, Fraction(0, 1), w
    raise ValueError('unknown mode')


def time_lower_bound(local_mib, remote_mib, local_bw_mib_s, remote_bw_mib_s):
    if local_mib < 0 or remote_mib < 0:
        raise ValueError('bytes must be non-negative')
    if local_bw_mib_s <= 0 or remote_bw_mib_s <= 0:
        raise ValueError('bandwidth must be positive')
    lt = Fraction(local_mib, local_bw_mib_s) if local_mib > 0 else Fraction(0, 1)
    rt = Fraction(remote_mib, remote_bw_mib_s) if remote_mib > 0 else Fraction(0, 1)
    return lt if lt > rt else rt


def bad_shared_time(weight_mib, local_bw_mib_s):
    return Fraction(weight_mib, local_bw_mib_s)


def page_count(num_bytes, page_bytes):
    if num_bytes < 0 or page_bytes <= 0:
        raise ValueError('bad page count input')
    if num_bytes == 0:
        return 0
    return (num_bytes + page_bytes - 1) // page_bytes


def panel_tlb_pages(mc, kc, nr, elem_bytes, page_bytes):
    if mc < 0 or kc < 0 or nr < 0 or elem_bytes <= 0 or page_bytes <= 0:
        raise ValueError('bad panel input')
    a = mc * kc * elem_bytes
    b = kc * nr * elem_bytes
    c = mc * nr * elem_bytes
    return page_count(a, page_bytes) + 2 * (page_count(b, page_bytes) + page_count(c, page_bytes))


def bad_tlb_a_only(mc, kc, elem_bytes, page_bytes):
    a = mc * kc * elem_bytes
    return page_count(a, page_bytes)


def panel_cache_bytes(mc, kc, nr, elem_bytes):
    if mc < 0 or kc < 0 or nr < 0 or elem_bytes <= 0:
        raise ValueError('bad cache panel input')
    return mc * kc * elem_bytes + kc * nr * elem_bytes + mc * nr * elem_bytes


def roofline_lb(flops, peak_flops, data_bytes, bandwidth, sync_time=0):
    if flops < 0 or peak_flops < 0 or data_bytes < 0 or bandwidth < 0 or sync_time < 0:
        raise ValueError('negative roofline input')
    if flops > 0 and peak_flops <= 0:
        raise ValueError('positive flops needs positive peak')
    if data_bytes > 0 and bandwidth <= 0:
        raise ValueError('positive bytes needs positive bandwidth')
    comp = Fraction(flops, peak_flops) if flops > 0 else Fraction(0, 1)
    mem = Fraction(data_bytes, bandwidth) if data_bytes > 0 else Fraction(0, 1)
    body = comp if comp > mem else mem
    return body + sync_time


def bad_roofline_sum(flops, peak_flops, data_bytes, bandwidth):
    comp = Fraction(flops, peak_flops)
    mem = Fraction(data_bytes, bandwidth)
    return comp + mem


def main():
    print('scope: offline CPU-serving integer/rational model; no counters, no hardware calls, no measurements')
    try:
        check('effective cores mins cpuset and quota', effective_cores(8, 400, 100) == Fraction(4, 1))
        check('effective cores not capped by larger quota', effective_cores(4, 800, 100) == Fraction(4, 1))
        check('unlimited quota uses cpuset', effective_cores(6, None, 100) == Fraction(6, 1))
        check('model slots subtract host reserve', model_slots(8, 400, 100, 1) == Fraction(3, 1))
        check('2 workers x 2 threads exceeds 3 model slots', plan_ok(2, 2, 8, 400, 100, 1) is False)
        check('1 worker x 3 threads fits 3 model slots', plan_ok(1, 3, 8, 400, 100, 1) is True)
        detect('host-core plan instead of cgroup quota', plan_ok(2, 2, 8, 400, 100, 1), bad_plan_ok_host_cores(2, 2, 64, 1))
        expect_error('negative cpuset rejected', effective_cores, -1, 100, 100)
        expect_error('zero period rejected', effective_cores, 8, 100, 0)

        weight = 20480
        kv = 15360
        cap = 32768
        check('full replica fails per-domain capacity', capacity_ok('full', weight, kv, cap) is False)
        check('shared weight fits per-domain capacity', capacity_ok('shared', weight, kv, cap) is True)
        check('sharded weight fits per-domain capacity', capacity_ok('sharded', weight, kv, cap) is True)
        detect('total capacity hides per-domain replica', capacity_ok('full', weight, kv, cap), bad_capacity_total('full', weight, kv, cap))

        local_bw = 100 * 1024
        remote_bw = 25 * 1024
        f_local, f_remote, f_unique = traffic_mib('full', weight)
        s_local, s_remote, s_unique = traffic_mib('shared', weight)
        h_local, h_remote, h_unique = traffic_mib('sharded', weight)
        check('full replica traffic conservation', f_local + f_remote == f_unique)
        check('shared traffic conservation', s_local + s_remote == s_unique)
        check('sharded traffic conservation', h_local + h_remote == h_unique)
        full_time = time_lower_bound(f_local, f_remote, 2 * local_bw, remote_bw)
        shared_time = time_lower_bound(s_local, s_remote, local_bw, remote_bw)
        sharded_time = time_lower_bound(h_local, h_remote, 2 * local_bw, remote_bw)
        check('shared remote path lower bound is 0.4 s', shared_time == Fraction(2, 5))
        check('full local lower bound is 0.2 s', full_time == Fraction(1, 5))
        check('sharded local lower bound is 0.1 s before reduction', sharded_time == Fraction(1, 10))
        detect('shared all-local traffic', shared_time, bad_shared_time(weight, local_bw))
        expect_error('negative traffic rejected', time_lower_bound, -1, 0, local_bw, remote_bw)

        mc, kc, nr, elem, page = 240, 256, 4, 8, 4096
        full_pages = panel_tlb_pages(mc, kc, nr, elem, page)
        a_only = bad_tlb_a_only(mc, kc, elem, page)
        check('full panel TLB pages is 128', full_pages == 128)
        check('A-only panel fits an undersized 125-entry model', a_only <= 125)
        check('full B/C double-buffer does not fit 125 entries', full_pages > 125)
        detect('A-only TLB accounting', full_pages <= 125, a_only <= 125)
        exact_pages = page_count(8192, 4096)
        check('exact page multiple has no extra page', exact_pages == 2)
        check('zero bytes has zero pages', page_count(0, 4096) == 0)
        expect_error('zero page size rejected', page_count, 1, 0)
        cache_full = panel_cache_bytes(mc, kc, nr, elem)
        cache_cap = 500000
        check('A panel alone fits cache cap', a_only * page <= cache_cap)
        check('A+B+C panel exceeds cache cap', cache_full > cache_cap)
        detect('A-only cache accounting', cache_full <= cache_cap, a_only * page <= cache_cap)

        check('roofline lower bound uses max not sum', roofline_lb(1000, 1000, 4000, 1000, 0) == Fraction(4, 1))
        check('roofline zero work plus sync', roofline_lb(0, 0, 0, 0, 2) == Fraction(2, 1))
        detect('roofline sum double-counts overlap', roofline_lb(1000, 1000, 4000, 1000, 0), bad_roofline_sum(1000, 1000, 4000, 1000))
        expect_error('negative roofline input rejected', roofline_lb, -1, 1000, 0, 1000, 0)

        print('RESULT: PASS')
        return 0
    except AssertionError as exc:
        print('FAIL: ' + str(exc))
        print('RESULT: FAIL')
        return 1
    except Exception as exc:
        print('FAIL: unexpected ' + repr(exc))
        print('RESULT: FAIL')
        return 1


if __name__ == '__main__':
    sys.exit(main())
